      "document_id": "50",
      "label": "0",
      "explanation": "Senator Reid criticizes the Bush Administration's policy on global warming. Criticisms of the executive branch or political opponents without claiming credit for a positive resolution are excluded from credit-claiming."
    },
    {
      "document_id": "1021",
      "label": "1",
      "explanation": "Senators Wyden and Smith announce and take credit for gaining Senate Appropriations Committee approval for funding salmon recovery and ocean research projects in Oregon, emphasizing the positive impacts of these federal dollars."
    }
  ]
}

